import sys
import runpy

def test_pylint_does_not_remove_first_sys_path_entry():
    sys.path.insert(0, "something")
    original = sys.path[0]
    try:
        runpy.run_module('pylint', run_name="__main__", alter_sys=True)
    except SystemExit:
        pass
    assert sys.path[0] == original, f"Expected sys.path[0] to stay {original!r}, got {sys.path[0]!r}"
